"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["99677"],{10293(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.estrutura_formulario.revisao_e_aceite_fora_do_fim","status":422,"titulo":"A revis\xe3o e aceite \xe9 sempre a \xfaltima p\xe1gina"},"descricao":{"codigo":"uniplus.estrutura_formulario.revisao_e_aceite_fora_do_fim","requisitos":[],"oQueAconteceu":["O formul\xe1rio tem o bloco `REVISAO_E_ACEITE`, mas a p\xe1gina de maior `ordem` \xe9 outra. \xc9 na revis\xe3o e aceite que o candidato confere as respostas e aceita o envio, e por isso nada pode vir depois dela. A mensagem \xe9 \\"A revis\xe3o e aceite \xe9 sempre a \xfaltima p\xe1gina do formul\xe1rio.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `paginas`; nos modelos de formul\xe1rio o `field` come\xe7a por `conteudo.`. Nada \xe9 gravado.","Quando o formul\xe1rio n\xe3o tem o bloco, a recusa \xe9 a de [bloco exigido ausente](/erros/uniplus.estrutura_formulario.bloco_exigido_ausente), e n\xe3o esta. A estrutura das p\xe1ginas s\xf3 \xe9 conferida quando todas as p\xe1ginas t\xeam forma v\xe1lida, e as recusas da estrutura saem juntas, na mesma lista. Na grava\xe7\xe3o do formul\xe1rio do processo, a forma de cada p\xe1gina \xe9 conferida primeiro e, havendo recusa, a estrutura s\xf3 \xe9 conferida se todas as p\xe1ginas foram formadas. No modelo, a estrutura s\xf3 \xe9 conferida quando o conte\xfado n\xe3o tem nenhuma outra recusa de forma, e os itens s\xe3o conferidos contra as p\xe1ginas s\xf3 depois que a estrutura das p\xe1ginas passa. Nos modelos de formul\xe1rio, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["D\xea ao bloco de revis\xe3o e aceite a maior `ordem` entre as p\xe1ginas, ou reduza a `ordem` das demais. Depois disso, grave de novo."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o do formul\xe1rio do processo"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Estrutura formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);